  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Build edges with mutual reachability
    edges = []
    for a, b, d in distances:
        n1, n2 = (a, b) if a <= b else (b, a)  # canonical order
        w = max(core_dist[n1], core_dist[n2], d)
        edges.append((w, n1, n2))

    # Sort by weight, then first node, then second node
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find (Disjoint Set)
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path compression
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for w, n1, n2 in edges:
        if union(n1, n2):
            mst_edges.append([n1, n2, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Graph disconnected; MST could not be built')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }
